 * Buatlah program yang melakukan hal berikut:
 * 1. Buat sebuah variabel bernama age dengan nilai bebas.
 * 2. Jika age kurang dari 13 → tampilkan "Anak-anak".
 * 3. Jika age antara 13 sampai 17 → tampilkan "Remaja".
 * 4. Jika age antara 18 sampai 59 → tampilkan "Dewasa".
 * 5. Jika age 60 ke atas → tampilkan "Lansia".
 * 6. Gunakan console.log untuk menampilkan hasilnya.
 */

const age = 60;

if (age < 13) {
    console.log('Anak-Anak');
} else if (age >= 13 & age <= 17) {
    console.log('Remaja');
} else if (age >= 18 & age <= 59) {
    console.log('Dewasa')
} else {
    console.log('Lansia')
}

function categorizeNumber(input) {
  /**
   * TODO:
   * Lengkapilah fungsi ini agar dapat menghasilkan output berupa kategori bilangan berdasarkan input yang diberikan.
   * Dengan ketentuan sebagai berikut:
   * 1. Jika input bukan number, bangkitkan (throw) error.
   * 2. Jika input adalah bilangan genap, kembalikan dengan nilai "Genap".
   * 3. Jika input adalah bilangan ganjil, kembalikan dengan nilai "Ganjil".
   * 4. Jika input adalah bilangan prima, kembalikan dengan nilai "Prima".
   * 5. Jika input adalah nol, kategorikan kembalikan dengan nilai "Nol".
   * 6. Jika input negatif, kembalikan dengan nilai "Negatif".
   */

if (typeof input !== "number") {
  throw new Error("Input harus berupa bilangan bulat");
} 

if (input === 0) {return ("Nol")} 
else if (input < 0) {return ("Negatif")}

if (input > 1) {
    let isPrime = true;
    for (let i = 2; i <= Math.sqrt(input); i++) {
      if (input % i === 0) {
        isPrime = false;
        break;
      }
    }
    if (isPrime) return "Prima";
  }

if (input % 2 == 0) {return ("Genap")} 
else {return ("Ganjil")} 


}

// Contoh
console.log(categorizeNumber(15)); // Output: "Ganjil"
console.log(categorizeNumber(12)); // Output: "Genap"
console.log(categorizeNumber(17)); // Output: "Prima"
console.log(categorizeNumber(0)); // Output: "Nol"
console.log(categorizeNumber(-5)); // Output: "Negatif"

try {
  categorizeNumber('abc');
} catch (error) {
  console.log(error.message);
} // Output: "Input harus berupa bilangan bulat"

/**
 * TODO:
 * Buatlah program untuk menampilkan angka dari 1 sampai 50 dengan ketentuan:
 * 1. Jika angka habis dibagi 3 tampilkan "Fizz".
 * 2. Jika angka habis dibagi 5 tampilkan "Buzz".
 * 3. Jika angka habis dibagi 3 dan 5 tampilkan "FizzBuzz".
 * 4. Jika tidak memenuhi kondisi di atas tampilkan angkanya sendiri.
 * 5. Gunakan perulangan (loop).
 */


for (let i = 1; i <= 50; i++) {

    if (i % 3 === 0 && i % 5 === 0) {
        console.log("FizzBuzz");

    } else if (i % 3 === 0) {
        console.log("Fizz");

    } else if (i % 5 === 0) {
        console.log("Buzz");

    } else {
        console.log(i);
    }

}

